// One sheet row per hotel. Empty cells mean Google showed no price for these dates (for example, sold out).
const rows = [];
for (const { json: h } of $input.all()) {
  if (!h.hotelName) continue; // skip empty responses
  rows.push({
    json: {
      checkedAt: (h.scrapedAt || new Date().toISOString()).slice(0, 16).replace('T', ' '),
      hotel: h.hotelName,
      checkIn: h.checkIn,
      checkOut: h.checkOut,
      nights: h.nights,
      currency: h.currency,
      pricePerNight: h.pricePerNight ?? '',
      pricePerNightWithTaxes: h.pricePerNightWithTaxes ?? '',
      totalForStay: h.priceTotal ?? '',
      deal: h.dealLabel ?? '',
      cheapestSite: h.cheapestProvider ?? '',
      hotelId: h.entityId,
    },
  });
}
return rows;
